// Validation de la trame JSON provenant de l'ESP32
var payload = msg.payload;

// Parse JSON si c'est une chaine
if (typeof payload === 'string') {
    try {
        payload = JSON.parse(payload);
    } catch(e) {
        node.warn('JSON invalide: ' + e.message);
        return null;
    }
}

// Champs requis minimum
var required = ['temperature_c', 'pressure_hpa'];
for (var i = 0; i < required.length; i++) {
    if (payload[required[i]] === undefined || payload[required[i]] === null) {
        node.warn('Champ manquant: ' + required[i]);
        // On continue quand meme (l imputer gerera les NaN)
    }
}

// Validation des bornes physiques
if (payload.temperature_c !== undefined) {
    if (payload.temperature_c < -50 || payload.temperature_c > 200) {
        node.warn('temperature_c hors bornes: ' + payload.temperature_c);
    }
}
if (payload.voltage_v !== undefined) {
    if (payload.voltage_v < 0 || payload.voltage_v > 35) {
        node.warn('voltage_v hors bornes: ' + payload.voltage_v);
    }
}

msg.original_payload = JSON.parse(JSON.stringify(payload));
msg.payload = payload;
msg.validated = true;
msg.timestamp = new Date().toISOString();
return msg;

// Preparation des features pour le modele ML
// IMPORTANT: utiliser exactement les memes features qu'a l'entrainement
// Interdits: fault_injection_level_pct, failure_type, failure_event, anomaly_reference

var d = msg.payload;

var ml_input = {
    ambient_temp_c:           d.ambient_temp_c           || null,
    humidity_pct:             d.humidity_pct             || null,
    altitude_m:               d.altitude_m               || null,
    airspeed_kts:             d.airspeed_kts             || null,
    load_pct:                 d.load_pct                 || null,
    operating_hours:          d.operating_hours          || null,
    flight_cycle_count:       d.flight_cycle_count       || null,
    cycles_since_maintenance: d.cycles_since_maintenance || null,
    maintenance_age_days:     d.maintenance_age_days     || null,
    temperature_c:            d.temperature_c            || null,
    atmospheric_pressure_hpa: d.atmospheric_pressure_hpa || null,
    pressure_hpa:             d.pressure_hpa             || null,
    vibration_x_ms2:          d.vibration_x_ms2          || null,
    vibration_y_ms2:          d.vibration_y_ms2          || null,
    vibration_z_ms2:          d.vibration_z_ms2          || null,
    vibration_norm_ms2:       d.vibration_norm_ms2       || null,
    voltage_v:                d.voltage_v                || null,
    current_a:                d.current_a                || null,
    power_w:                  d.power_w                  || null,
    energy_wh_interval:       d.energy_wh_interval       || null,
    rpm:                      d.rpm                      || null,
    motor_current_temp_c:     d.motor_current_temp_c     || null,
    wifi_rssi_dbm:            d.wifi_rssi_dbm            || null,
    packet_latency_ms:        d.packet_latency_ms        || null
};

msg.ml_input  = ml_input;
msg.payload   = ml_input;
msg.headers   = {'Content-Type': 'application/json'};
msg.method    = 'POST';
msg.url       = 'http://localhost:5000/predict';

return msg;

// Fusion des donnees capteurs et du resultat ML
var ml_result  = msg.payload;
var sensor_data = msg.original_payload || {};

// Construction du message unifie pour InfluxDB
msg.payload = {
    // Donnees capteurs
    temperature_c:            sensor_data.temperature_c,
    pressure_hpa:             sensor_data.pressure_hpa,
    humidity_pct:             sensor_data.humidity_pct,
    altitude_m:               sensor_data.altitude_m,
    airspeed_kts:             sensor_data.airspeed_kts,
    vibration_norm_ms2:       sensor_data.vibration_norm_ms2,
    voltage_v:                sensor_data.voltage_v,
    current_a:                sensor_data.current_a,
    power_w:                  sensor_data.power_w,
    rpm:                      sensor_data.rpm,
    operating_hours:          sensor_data.operating_hours,
    // Resultats ML
    ml_anomaly:               ml_result.anomaly,
    ml_anomaly_score:         ml_result.anomaly_score,
    ml_status:                ml_result.status,
    ml_threshold:             ml_result.threshold,
    ml_model:                 ml_result.model
};

// Log si anomalie
if (ml_result.anomaly === 1) {
    node.warn('ANOMALIE DETECTEE | score=' + ml_result.anomaly_score + ' | ' + new Date().toISOString());
}

msg.ml_result = ml_result;
return msg;

node.error('Erreur API ML: ' + msg.error.message);
// Envoyer quand meme les donnees capteurs sans le resultat ML
msg.payload = msg.original_payload || {};
msg.payload.ml_anomaly = -1;
msg.payload.ml_status = 'ERROR';
msg.payload.ml_error = msg.error.message || 'API indisponible';
return msg;

if (msg.ml_result && msg.ml_result.anomaly === 1) {
    // Declencher une alerte
    var alert_msg = {
        payload: {
            type:    'ANOMALY_ALERT',
            message: 'Anomalie detectee sur equipement aeronautique',
            score:   msg.ml_result.anomaly_score,
            time:    new Date().toISOString()
        }
    };
    return alert_msg;
}
return null;
